# -*- coding: utf-8 -*-
"""Canonical MIS question bank — chapters 8, 9, 10."""
from bank_a import q

# ============================ CHAPTER 8 ============================

q(id='C8-01', ch=8, types=['دورة','كتاب'], qtype='MCQ', freq=3, src=['BKQ','S25','F24'], page=302,
  text='شبكة من المؤسسات والعمليات التجارية لشراء المواد الخام وتحويل هذه المواد إلى منتجات وسيطة ومنتهية وتوزيع المنتجات النهائية على العملاء، تُسمى:',
  opts=['قناة التوزيع','سلسلة الإمداد (التوريد) Supply Chain','سلسلة القيمة','سلسلة التسويق'],
  ans='سلسلة التوريد Supply Chain',
  exp='سلسلة التوريد Supply Chain هي شبكة من المنظمات والعمليات التجارية لشراء المواد الخام، وتحويل هذه المواد إلى منتجات وسيطة ومنتهية، وتوزيع المنتجات النهائية على العملاء. وهي تربط بين الموردين ومصانع التصنيع ومراكز التوزيع ومنافذ البيع بالتجزئة والعملاء. وتتدفق المواد والمعلومات والمدفوعات عبر سلسلة التوريد في كلا الاتجاهين.')

q(id='C8-02', ch=8, types=['دورة'], qtype='MCQ', freq=3, src=['S25','F24','R44'], page=303,
  text='موردو الشركة وموردو الموردين والعمليات الخاصة بإدارة العلاقات معهم يقعون ضمن:',
  opts=['الجزء العلوي من سلسلة التوريد Upstream','الجزء السفلي من سلسلة التوريد Downstream','سلسلة التوريد الداخلية','سلسلة القيمة الموسّعة'],
  ans='الجزء العلوي من سلسلة التوريد Upstream',
  exp='يشمل **الجزء العلوي Upstream** من سلسلة التوريد موردي الشركة وموردي الموردين والعمليات الخاصة بإدارة العلاقات معهم. أما **الجزء السفلي Downstream** فيتكون من المنظمات والعمليات الخاصة بتوزيع وتسليم المنتجات إلى العملاء النهائيين. كما تقوم الشركات المصنّعة بإدارة **عمليات سلسلة التوريد الداخلية Internal Supply Chain Processes**. ملاحظة: موردو الوجوه والنعال والأربطة هم الموردون الثانويون (المستوى 2)، وموردوهم هم موردو المستوى 3.')

q(id='C8-03', ch=8, types=['دورة'], qtype='DEF', freq=2, src=['HD','R44'], page=304,
  text='ما هو تأثير كرة الثلج أو السوط Bullwhip Effect؟ وكيف يتم تخفيفه؟',
  ans='تشويه المعلومات حول الطلب على المنتج أثناء انتقاله من كيان إلى آخر عبر سلسلة التوريد؛ ويُخفَّف بالحد من عدم اليقين حول الطلب والعرض عبر مشاركة معلومات دقيقة ومحدّثة وديناميكية',
  exp='**تأثير السوط Bullwhip Effect** هو من المشاكل المتكررة في إدارة سلسلة التوريد، حيث يتم تشويه المعلومات حول الطلب على المنتج أثناء انتقاله من كيان إلى آخر عبر سلسلة التوريد. فقد يؤدي الارتفاع الطفيف في الطلب على عنصر ما إلى قيام أعضاء مختلفين في سلسلة التوريد بزيادة طفيفة على المخزون للاستخدام عند الحاجة، وعندما تنتشر هذه التغييرات في أنحاء السلسلة يحصل تضخيم كبير في المخزون وتكاليف الإنتاج والتخزين والشحن. **التخفيف**: الحد من عدم اليقين بشأن الطلب والعرض عندما يكون لدى جميع أعضاء سلسلة التوريد معلومات دقيقة ومحدّثة وديناميكية — وهذا ما توفّره أنظمة إدارة سلسلة التوريد SCM.')

q(id='C8-04', ch=8, types=['دورة'], qtype='DEF', freq=2, src=['F24','R44'], page=298,
  text='تعريف أنظمة المؤسسة Enterprise Systems',
  ans='مجموعة من وحدات البرامج المتكاملة وقاعدة بيانات مركزية مشتركة تجمع المعطيات من العديد من الأقسام والإدارات وإجراءات العمل الرئيسة وتتيحها لكل التطبيقات',
  exp='أنظمة المؤسسة Enterprise Systems — والمعروفة أيضاً بأنظمة تخطيط موارد المؤسسة **ERP** — تستند إلى مجموعة من وحدات البرامج المتكاملة وقاعدة بيانات مركزية مشتركة. تجمع قاعدة البيانات المعطيات من العديد من الأقسام والإدارات ومن عدد كبير من إجراءات العمل الرئيسة في مجالات التصنيع والإنتاج والمالية والمحاسبة والمبيعات والتسويق والموارد البشرية، مما يجعل البيانات متاحة للتطبيقات التي تدعم جميع أنشطة الأعمال الداخلية. وعند إدخال معلومات جديدة بوساطة إجراء عمل معين، يتم إتاحتها فوراً لإجراءات العمل الأخرى.')

q(id='C8-05', ch=8, types=['كتاب'], qtype='MCQ', freq=1, src=['BKQ'], page=298,
  text='مجموعة من وحدات البرامج المتكاملة للتمويل والمحاسبة والموارد البشرية والتصنيع والإنتاج والمبيعات والتسويق التي تسمح باستخدام البيانات من خلال وظائف وعمليات تجارية متعددة، تصف على أفضل وجه ما يلي:',
  opts=['برنامج إدارة العمليات','برامج المؤسسات','برامج التعاون','برامج التطبيقات'],
  ans='برامج المؤسسات Enterprise Software',
  exp='أنظمة المؤسسة تستند إلى مجموعة من وحدات البرامج المتكاملة وقاعدة بيانات مركزية مشتركة يمكن من خلالها مشاركة البيانات لإجراءات العمل والمجالات الوظيفية في جميع أنحاء المؤسسة — التمويل والمحاسبة والموارد البشرية والتصنيع والإنتاج والمبيعات والتسويق.')

q(id='C8-06', ch=8, types=['كتاب'], qtype='MCQ', freq=1, src=['BKQ'], page=299,
  text='تم تصميم هذا البرنامج حول آلاف العمليات التجارية المعرّفة مسبقاً:',
  opts=['برمجيات إدارة العمليات','برامج التعاون','برامج المؤسسات','برامج المجموعة'],
  ans='برامج المؤسسات Enterprise Software',
  exp='برمجيات المؤسسات Enterprise Software تم تصميمها حول آلاف إجراءات العمل المحددة مسبقاً والتي تعكس أفضل الممارسات. لذلك يتعين على الشركات التي تنفذ هذه الأنظمة أولاً تحديد وظائف النظام التي ترغب في استخدامها، ثم مطابقة إجراءات عملها مع إجراءات العمل المحددة والمعرّفة مسبقاً ضمن النظام.')

q(id='C8-07', ch=8, types=['كتاب'], qtype='MCQ', freq=1, src=['BKQ'], page=299,
  text='تستند خرائط العمليات أو النماذج المرجعية التي يقدمها موردو برامج المؤسسة إلى المعرفة بعملية الأعمال و:',
  opts=['البيع المتبادل','أفضل الممارسات Best Practices','المقاييس','طرازات الدفع'],
  ans='أفضل الممارسات Best Practices',
  exp='تم تصميم برمجيات المؤسسات حول آلاف إجراءات العمل المحددة مسبقاً **والتي تعكس أفضل الممارسات Best Practices**. وإذا كان نظام المؤسسة لا يدعم الطريقة التي تعمل بها الشركة فيمكن إعادة كتابة بعض البرامج، لكن التخصيص الشامل قد يؤدي إلى انخفاض أداء النظام؛ ولذلك ينبغي على الشركات تغيير طريقتها لتتوافق مع إجراءات العمل المعرّفة ضمن النظام.')

q(id='C8-08', ch=8, types=['كتاب'], qtype='MCQ', freq=1, src=['BKQ'], page=307,
  text='تخطيط ومراقبة جميع العوامل التي تؤثر على نقل منتج أو خدمة ما، تحدد على أفضل وجه:',
  opts=['الحصول على المعلومات','البحث والتطوير','اللوجستية (الخدمات اللوجستية)','المشتريات'],
  ans='اللوجستية Logistics',
  exp='الخدمات اللوجستية Logistics هي تخطيط ومراقبة جميع العوامل التي تؤثر على نقل منتج أو خدمة. وقد شجّعت العولمة على الاستعانة بمصادر خارجية لإدارة المستودعات وإدارة النقل وعمليات مزوّدي الخدمات اللوجستية من الأطراف الثالثة Third-Party Logistics، والتي تقدّم هذه الخدمات باستخدام برامج تعتمد على الويب لإعطاء عملائها رؤية أفضل لسلاسل التوريد العالمية.')

q(id='C8-09', ch=8, types=['كتاب'], qtype='MCQ', freq=1, src=['BKQ'], page=318,
  text='يُعد تحليل إنتاجية ممثل المبيعات وممثل خدمة العملاء مثالاً على:',
  opts=['البيع المتبادل','إدارة علاقات العملاء التشغيلية Operational CRM','إدارة علاقات العملاء التحليلية Analytical CRM','التجميع'],
  ans='إدارة علاقات العملاء التحليلية Analytical CRM',
  exp='**نظام CRM التشغيلي Operational CRM** يتضمن التطبيقات التي تتعامل مباشرة مع العملاء، مثل أدوات أتمتة فرق المبيعات ومركز الاتصال ودعم خدمة العملاء والأتمتة التسويقية. أما **نظام CRM التحليلي Analytical CRM** فيتضمن التطبيقات التي تقوم **بتحليل بيانات العملاء** التي أنشأتها التطبيقات التشغيلية لتوفير المعلومات لتحسين أداء الأعمال — ومنه تحليل إنتاجية ممثلي المبيعات وخدمة العملاء، وتحديد العملاء المربحين وغير المربحين، وحساب قيمة حياة العميل.')

q(id='C8-10', ch=8, types=['دورة'], qtype='DEF', freq=1, src=['S25'], page=319,
  text='هي العلاقة بين الإيرادات التي ينتجها عميل معين والنفقات المتكبدة في الحصول عليه وتقديم الخدمات له والعمر المتوقع للعلاقة معه:',
  ans='قيمة حياة العميل Customer Lifetime Value (CLTV)',
  exp='**قيمة حياة العميل Customer Lifetime Value (CLTV)** هي من النتائج المهمة لنظام CRM التحليلي، وتستند إلى العلاقة بين الإيرادات التي ينتجها عميل معين، والنفقات المتكبدة في الحصول على هذا العميل وتقديم الخدمات له، والعمر المتوقع للعلاقة بين العميل والشركة.')

q(id='C8-11', ch=8, types=['دورة'], qtype='MCQ', freq=2, src=['F24','R44'], page=316,
  text='مَن يحدّد فرص البيع المتقاطع Cross-selling؟',
  opts=['نظم إدارة علاقات العملاء CRM','نظم إدارة سلسلة التوريد SCM','نظم المؤسسة ERP','نظم إدارة المعرفة KMS'],
  ans='نظم إدارة علاقات العملاء CRM',
  exp='تدعم نظم CRM حملات التسويق المباشر Direct-Marketing من خلال توفير إمكانيات لالتقاط بيانات العملاء الحاليين والمحتملين، وتوفير معلومات المنتج والخدمة، وتأهيل العملاء المحتملين للتسويق المستهدف، وجدولة وتتبع المراسلات التسويقية. وتتضمن وحدات التسويق أدوات لتحليل بيانات التسويق والعملاء، وتحديد العملاء المربحين وغير المربحين، وتصميم المنتجات والخدمات، **وتحديد فرص البيع المتقاطع Cross-selling** وهو تسويق المنتجات التكميلية للعملاء (مثال: بيع حساب نقدي أو قرض عقاري لعميل لديه حساب شيكات فقط).')

q(id='C8-12', ch=8, types=['دورة'], qtype='DEF', freq=1, src=['HD'], page=315,
  text='تعريف التسويق المباشر Direct-Marketing في نظم CRM',
  ans='توفير إمكانية لالتقاط بيانات العملاء الحاليين والمحتملين، وتوفير معلومات المنتج والخدمة، وتأهيل العملاء المحتملين للتسويق المستهدف، وجدولة وتتبع المراسلات التسويقية',
  exp='تدعم أنظمة CRM حملات التسويق المباشر من خلال توفير إمكانيات لالتقاط بيانات العملاء الحاليين والمحتملين، وتوفير معلومات المنتج والخدمة، وتأهيل العملاء المحتملين للتسويق المستهدف، وجدولة وتتبع المراسلات التسويقية المباشرة أو البريد الإلكتروني. كما تتضمن وحدات التسويق أدوات لتحليل بيانات التسويق والعملاء وتحديد فرص البيع المتقاطع.')

q(id='C8-13', ch=8, types=['دورة'], qtype='MCQ', freq=1, src=['F24'], page=322,
  text='تطبيقات المؤسسات من الجيل التالي (الثاني) تتضمن حلولاً:',
  opts=['سحابية ومفتوحة المصدر ومتاحة على منصات الأجهزة المحمولة','مركزية فقط','مغلقة المصدر فقط','محلية داخل الشركة فقط'],
  ans='سحابية (ومفتوحة المصدر، وعلى منصات الأجهزة المحمولة)',
  exp='أصبحت أنظمة ERP و SCM و CRM المستقلة والقائمة بذاتها شيئاً من الماضي، فأنشأ بائعو برامج المؤسسات الرئيسة ما يسمّونه **حلول المؤسسات Enterprise Solutions** أو **مجموعات المؤسسات Enterprise Suites** أو **مجموعات الأعمال الإلكترونية E-Business Suites**. وتتضمن تطبيقات المؤسسات من الجيل التالي أيضاً **حلولاً مفتوحة المصدر وسحابية** إضافة إلى المزيد من الوظائف المتوفرة على منصات الأجهزة المحمولة. أمثلة: SAP Business Suite و Oracle E-Business Suite و Microsoft Dynamics Suite؛ ومفتوحة المصدر: Compiere و Openbravo؛ وسحابية: Salesforce.com.')

q(id='C8-14', ch=8, types=['كتاب'], qtype='TF', freq=1, src=['BKQ'], page=298,
  text='تتيح برامج المؤسسات استخدام البيانات من خلال وظائف وعمليات عمل متعددة لضمان التنسيق والتحكم الدقيق.',
  ans='صح',
  exp='العبارة صحيحة. تتميز أنظمة المؤسسات بمجموعة وحدات البرامج المتكاملة وقاعدة بيانات مركزية يمكن من خلالها مشاركة البيانات لإجراءات العمل والمجالات الوظيفية في جميع أنحاء المؤسسة، مما يتيح التنسيق والتحكم الدقيق. **ملاحظة تحريرية:** وردت العبارة في الكتاب بصيغة «... بين المؤسسات»، والأدق «داخل المؤسسة/على مستوى المؤسسة» لأن أنظمة المؤسسة تنسّق داخلياً بالدرجة الأولى.')

q(id='C8-15', ch=8, types=['كتاب'], qtype='TF', freq=1, src=['BKQ'], page=300,
  text='يمكن لأنظمة المؤسسات تحسين إعداد التقارير الإدارية واتخاذ القرارات.',
  ans='صح',
  exp='العبارة صحيحة. توفّر أنظمة المؤسسات الكثير من المعلومات القيّمة لتحسين عملية اتخاذ القرارات الإدارية. فيمكن لمقر الشركة الرئيس الوصول إلى بيانات دقيقة ومحدّثة عن المبيعات والمخزون والإنتاج، ويستخدم هذه المعلومات لبناء توقعات أكثر دقة. كما يتضمن نظام المؤسسات أدوات تحليلية لتقييم الأداء التنظيمي العام بتعريفات وتنسيقات موحدة ومقبولة من المؤسسة بأكملها.')

q(id='C8-16', ch=8, types=['كتاب'], qtype='TF', freq=1, src=['BKQ'], page=303,
  text='تكون سلاسل التوريد في شركات التصنيع الكبرى متعددة الطبقات.',
  ans='صح',
  exp='العبارة صحيحة. مثال الكتاب عن Nike: الموردون الأساسيون هم المصنّعون المتعاقدون، والموردون من الباطن للوجوه والنعال والأربطة هم **الموردون الثانويون (المستوى 2)**، وموردو هؤلاء الموردين الثانويين هم **موردو المستوى 3**. وهكذا تكون سلسلة التوريد متعددة الطبقات.')

q(id='C8-17', ch=8, types=['كتاب'], qtype='TF', freq=1, src=['BKQ'], page=307,
  text='لا يمكن استخدام شبكات الإنترانت لدمج المعلومات من العمليات التجارية المعزولة داخل الشركة لمساعدتها في إدارة سلاسل التوريد الداخلية بها.',
  ans='خطأ',
  exp='العبارة خاطئة. التصحيح: **يمكن** استخدام شبكات الإنترانت لدمج المعلومات من العمليات التجارية المعزولة داخل الشركة لمساعدتها في إدارة سلاسل التوريد الداخلية. فأنظمة إدارة سلسلة التوريد المحسّنة بتكنولوجيا الإنترنت توفّر هذا التكامل: يستخدم المدير واجهة ويب للاستفادة من أنظمة الموردين، ويستخدم الشركاء أدوات تعتمد على الويب للتعاون في التنبؤات، ويصل مندوبو المبيعات إلى جداول إنتاج الموردين ومعلومات الخدمات اللوجستية.')

q(id='C8-18', ch=8, types=['كتاب'], qtype='TF', freq=1, src=['BKQ'], page=319,
  text='يمكن لإدارة علاقات العملاء مساعدة المؤسسات على تحديد العملاء الذين يكلفون الشركة الكثير لجذبهم والاحتفاظ بهم.',
  ans='صح',
  exp='العبارة صحيحة. يقوم نظام CRM التحليلي بتحليل بيانات العملاء لتحديد أنماط الشراء وإنشاء قطاعات للتسويق المستهدف **وتحديد العملاء المربحين وغير المربحين**. ومن النتائج المهمة لهذا التحليل **قيمة حياة العميل CLTV** التي تقارن الإيرادات التي ينتجها العميل بالنفقات المتكبدة في الحصول عليه وخدمته.')

q(id='C8-19', ch=8, types=['كتاب'], qtype='TF', freq=1, src=['BKQ'], page=320,
  text='عند بناء أنظمة المؤسسات، يمكن تحديد الفوائد بسهولة في بداية المشروع.',
  ans='خطأ',
  exp='العبارة خاطئة. التصحيح: تتضمن تطبيقات المؤسسات قطعاً معقّدة من البرامج غالية الثمن للشراء والتنفيذ، وقد تستغرق شركة كبيرة **عدة سنوات** لإكمال تنفيذ واسع النطاق. ووفق دراسة استقصائية بلغ متوسط تكلفة مشروع ERP نحو 6.1 مليون دولار واستغرقت المشاريع وسطياً 15.7 شهراً، وقدّمت 53% من المشاريع أقل من 5% من الفوائد المتوقعة، وتجاوز نحو 58% موازناتها المخططة و65% جدولها الزمني. لذلك لا يمكن تحديد الفوائد بسهولة في بداية المشروع.')

q(id='C8-20', ch=8, types=['كتاب'], qtype='TF', freq=1, src=['BKQ'], page=320,
  text='من بين التحديات المرتبطة بأنظمة المؤسسات تحقيق القيمة الاستراتيجية.',
  ans='صح',
  exp='العبارة صحيحة. تتطلب تطبيقات المؤسسات تغييرات تكنولوجية عميقة وتغييرات أساسية في طريقة عمل الشركة وإجراءات عملها، ويجب على الموظفين قبول وظائف ومسؤوليات جديدة. كما تفرض تطبيقات المؤسسات **تكاليف التحويل** وتجعل الشركة معتمدة على بائع واحد، وهو أمر غير صحّي استراتيجياً. لذلك يُعد تحقيق القيمة الاستراتيجية من أبرز التحديات المرتبطة بها.')

q(id='C8-21', ch=8, types=['كتاب'], qtype='ESSAY', freq=1, src=['BKQ'], page=328,
  text='وضّح دور أنظمة المؤسسات في تحقيق التميز التشغيلي للمنظمة. {15 دقيقة – 15 من 100 – توجيه: الفقرة 8-1}',
  ans='توفّر التكامل، وتزيد الكفاءة التشغيلية، وتوفّر معلومات عالية القيمة لدعم القرار، وتفرض ممارسات وبيانات قياسية',
  exp='**المشكلة**: الشركات تدير معلوماتها بعشرات أو مئات قواعد البيانات والأنظمة التي لا يمكن لأي منها التحدث إلى الآخر، فتعتمد القرارات على تقارير مطبوعة قديمة. **الحل**: أنظمة المؤسسة ERP تستند إلى وحدات برامج متكاملة وقاعدة بيانات مركزية مشتركة تجمع المعطيات من مختلف الأقسام وتتيحها فوراً لكل إجراءات العمل. **القيمة التجارية**: (1) **زيادة الكفاءة التشغيلية** — عند تقديم طلب تتدفق البيانات تلقائياً إلى المستودع والمصنع والمحاسبة، ويعرف التصنيع بالضبط ما طلبه العملاء فقط، ويتم الحصول على العدد الصحيح من المكونات، وتقليل وقت بقاء المنتجات في المخزون. (2) **الاستجابة السريعة لطلبات العملاء** للمعلومات أو المنتجات. (3) **معلومات عالية القيمة لتحسين القرار** — بيانات دقيقة ومحدّثة عن المبيعات والمخزون والإنتاج لبناء توقعات أدق. (4) **فرض الممارسات والبيانات القياسية** بحيث يعمل الجميع بالطريقة نفسها في جميع أنحاء الشركة، مع تعريفات وتنسيقات موحدة لتقييم الأداء التنظيمي.')

q(id='C8-22', ch=8, types=['كتاب'], qtype='ESSAY', freq=1, src=['BKQ'], page=328,
  text='ما هي سلسلة التوريد؟ بيّن دور نظم المعلومات في أتمتة سلسلة التوريد من خلال أنظمة SCM. {15 دقيقة – 15 من 100 – توجيه: الفقرة 8-2}',
  ans='تعريف السلسلة وأجزاؤها، ثم دور SCM في التخطيط والتنفيذ وتخفيف تأثير السوط والانتقال من نموذج الدفع إلى نموذج السحب',
  exp='**التعريف**: سلسلة التوريد شبكة من المنظمات والعمليات التجارية لشراء المواد الخام وتحويلها إلى منتجات وسيطة ومنتهية وتوزيع المنتجات النهائية على العملاء؛ وتتدفق المواد والمعلومات والمدفوعات في الاتجاهين. أجزاؤها: **العلوي Upstream** (الموردون وموردوهم)، و**السفلي Downstream** (التوزيع والتسليم للعملاء)، و**الداخلي Internal**. **مشاكلها**: نقص الأجزاء، نقص طاقة المصنع، المخزون الزائد، ارتفاع تكاليف النقل — وسببها معلومات غير دقيقة أو غير متاحة في الوقت المناسب، وتهدر نحو 25% من تكاليف تشغيل الشركة. و**تأثير السوط Bullwhip Effect** يشوّه معلومات الطلب عبر السلسلة. **دور نظم المعلومات**: **(أ) أنظمة تخطيط سلسلة التوريد Supply Chain Planning** — تصميم السلسلة، وتوليد توقعات الطلب (تخطيط الطلب Demand Planning من أهم وظائفها وأعقدها)، وتحديد كميات التصنيع ومستويات المخزون ومواقع التخزين وآلية النقل. **(ب) أنظمة تنفيذ سلسلة التوريد Supply Chain Execution** — إدارة تدفق المنتجات عبر مراكز التوزيع والمستودعات وتتبع الحالة المادية للبضائع وإدارة المواد وعمليات التخزين والنقل. **(ج) الانتقال من نموذج الدفع Push إلى نموذج السحب Pull** — بدل التنبؤ ودفع المنتجات، تُنتج الطلبات الفعلية أحداثاً في السلسلة، مما يتيح سلاسل توريد متزامنة بدل تسلسلية. **(د) القيمة التجارية**: ربط العرض بالطلب، تخفيض المخزون، تحسين خدمة التسليم، تسريع وصول المنتج للسوق، واستخدام أكثر فعالية للأصول.')

q(id='C8-23', ch=8, types=['كتاب'], qtype='ESSAY', freq=1, src=['BKQ'], page=328,
  text='كيف تدعم نظم المعلومات أتمتة إدارة العلاقة مع الزبائن؟ {15 دقيقة – 15 من 100 – توجيه: الفقرة 8-3}',
  ans='التقاط ودمج بيانات العملاء من كل نقاط الاتصال وتحليلها وتوزيعها، عبر وحدات أتمتة المبيعات وخدمة العملاء والتسويق، وبنمطين تشغيلي وتحليلي',
  exp='**المشكلة**: تتفاعل الشركة مع العميل عبر قنوات متعددة (ويب، هاتف، بريد إلكتروني، مدونات، لقاء مباشر)، وتميل عمليات المبيعات والخدمات والتسويق إلى التقسيم، فلا توجد رؤية موحدة للعميل. **الحل**: تقوم أنظمة **CRM** بالتقاط ومكاملة بيانات العملاء من جميع أنحاء المؤسسة ومن كل **نقاط الاتصال Touch Points**، ودمجها وتحليلها، ثم توزيع النتائج على مختلف الأنظمة ونقاط الاتصال. **الوحدات الرئيسة**: (1) **أتمتة قوة المبيعات SFA** — معلومات العملاء المحتملين وجهات الاتصال وتشكيل المنتج وعرض الأسعار وتجميع مشتريات العميل السابقة لتقديم توصيات مخصصة، مما يزيد كفاءة كل مندوب ويقلل تكلفة البيع واكتساب العملاء. (2) **خدمة العملاء** — توجيه المكالمة إلى الموظف الصحيح وإدارة طلبات الخدمة وقدرات الخدمة الذاتية عبر الويب، مما يرفع الإنتاجية ويقلل مدة المعاملة. (3) **التسويق** — دعم حملات التسويق المباشر وتحليل بيانات التسويق والعملاء وتحديد فرص **البيع المتقاطع Cross-selling**. **النمطان**: **CRM التشغيلي** (التطبيقات التي تتعامل مباشرة مع العملاء) و**CRM التحليلي** (تحليل بيانات العملاء من التطبيقات التشغيلية باستخدام OLAP والتنقيب في البيانات لتحديد الأنماط وقطاعات التسويق وحساب **قيمة حياة العميل CLTV**). **القيمة**: زيادة رضا العملاء، خفض تكاليف التسويق المباشر واكتساب العملاء، زيادة إيرادات المبيعات، وتقليل **معدل انسحاب العملاء Churn Rate**.')

# ============================ CHAPTER 9 ============================

q(id='C9-01', ch=9, types=['دورة','كتاب'], qtype='MCQ', freq=2, src=['BKQ','R44'], page=337,
  text='تسمى المعرفة التي تكمن في عقول الموظفين والتي لم يتم توثيقها بـ:',
  opts=['المعرفة الضمنية Tacit Knowledge','الذاكرة التنظيمية','إجراءات التشغيل الموحدة','ثقافة الشركات'],
  ans='المعرفة الضمنية Tacit Knowledge',
  exp='**المعرفة الضمنية Tacit Knowledge** هي المعرفة الموجودة في أذهان الموظفين والتي لم تُوثَّق. أما المعرفة التي تم توثيقها فتُسمى **المعرفة الصريحة Explicit Knowledge**. ويمكن أن تتواجد المعرفة في البريد الإلكتروني والبريد الصوتي والرسومات والمستندات غير المهيكلة وكذلك المستندات المهيكلة.')

q(id='C9-02', ch=9, types=['كتاب'], qtype='MCQ', freq=1, src=['BKQ'], page=337,
  text='تُصنف خبرة وتجارب المنظمة التي لم يتم توثيقها رسمياً من قبل أعضائها بأنها:',
  opts=['الحكمة','المعلومات','البيانات','المعرفة الضمنية'],
  ans='المعرفة الضمنية Tacit Knowledge',
  exp='المعرفة الضمنية Tacit Knowledge هي المعرفة الموجودة في أذهان الموظفين والتي لم تُوثَّق رسمياً. والمعرفة سمة فردية وجماعية للشركة، وهي حدث معرفي بل وحتى فيزيولوجي يحدث داخل رؤوس الأشخاص، كما تُخزَّن في المكتبات والسجلات وتُشارَك في المحاضرات.')

q(id='C9-03', ch=9, types=['دورة'], qtype='DEF', freq=1, src=['HD'], page=337,
  text='تعريف الحكمة Wisdom',
  ans='التجربة الجماعية والفردية لتطبيق المعرفة على حل المشكلات، وتتضمن أين ومتى وكيف يتم تطبيق المعرفة',
  exp='**الحكمة Wisdom** هي التجربة الجماعية والفردية لتطبيق المعرفة على حل المشكلات، حيث تتضمن الحكمة **أين ومتى وكيف** يتم تطبيق المعرفة. وترتيب السلّم: **البيانات Data** (تدفقات الأحداث والمعاملات) ← **المعلومات Information** (البيانات مصنّفة ضمن فئات مفهومة ومحددة) ← **المعرفة Knowledge** (اكتشاف الأنماط والقواعد والسياقات) ← **الحكمة Wisdom**.')

q(id='C9-04', ch=9, types=['دورة'], qtype='DEF', freq=2, src=['S25','F24'], page=339,
  text='تعريف التعلم التنظيمي Organizational Learning',
  ans='عملية التغيير التي تقوم بها المنظمات لتعديل سلوكها بما يعكس ما تعلّمته، من خلال جمع البيانات والقياس الدقيق والتجريب وارتكاب الأخطاء والتعلم من الخبرة',
  exp='تُنشئ المؤسسات المعرفة وتجمعها باستخدام آليات التعلم التنظيمي المتنوعة: من خلال جمع البيانات والقياس الدقيق للأنشطة المخطط لها، والتجريب وارتكاب الأخطاء، ومن ردود العملاء والبيئة بشكل عام تكتسب المؤسسات الخبرة. وتقوم المؤسسات التي تتعلم بتعديل سلوكها لتعكس ذلك التعلم من خلال إنشاء إجراءات عمل جديدة وتغيير أنماط اتخاذ قرارات الإدارة — وتُسمى عملية التغيير هذه **التعلم التنظيمي Organizational Learning**. والمنظمات التي يمكنها استشعار بيئاتها والاستجابة لها تبقى لفترة أطول من المنظمات ذات آليات التعلم الضعيفة.')

q(id='C9-05', ch=9, types=['دورة'], qtype='MCQ', freq=1, src=['S25'], page=342,
  text='البوابات والبريد الإلكتروني والمراسلة الفورية وأدوات الأعمال الاجتماعية ومواقع Wiki ومحركات البحث هي أدوات مرحلة:',
  opts=['نشر المعرفة Knowledge Dissemination','اكتساب المعرفة','تخزين المعرفة','تطبيق المعرفة'],
  ans='نشر المعرفة Knowledge Dissemination',
  exp='**سلسلة قيمة إدارة المعرفة** أربع خطوات: (1) **اكتساب المعرفة** Knowledge Acquisition — بناء مستودعات للوثائق والتقارير وأفضل الممارسات وشبكات الخبراء. (2) **تخزين المعرفة** Knowledge Storage — قواعد البيانات وأنظمة إدارة المستندات. (3) **نشر المعرفة** Knowledge Dissemination — أضافت **البوابات والبريد الإلكتروني والمراسلة الفورية وأدوات الأعمال الاجتماعية ومواقع Wiki ومحركات البحث** إمكانات كبيرة لمشاركة التقويمات والمستندات والبيانات والرسومات. (4) **تطبيق المعرفة** Knowledge Application.')

q(id='C9-06', ch=9, types=['كتاب'], qtype='MCQ', freq=1, src=['BKQ'], page=341,
  text='مجموعة العمليات وإجراءات العمل والثقافة والسلوك المطلوب للحصول على قيمة من الاستثمارات في أنظمة المعلومات هي أحد أنواع:',
  opts=['ثقافة المعرفة','اكتشاف المعرفة','رأس المال التنظيمي والإداري','الروتين التنظيمي'],
  ans='رأس المال التنظيمي والإداري Organizational and Management Capital',
  exp='**رأس المال التنظيمي والإداري** هو مجموعة من إجراءات العمل والثقافة والسلوك المطلوب للحصول على قيمة من الاستثمارات في نظم المعلومات. وفي حالة إدارة المعرفة — كما هو الحال مع استثمارات نظم المعلومات الأخرى — يجب بناء القيم والهياكل وأنماط السلوك الداعمة لزيادة العائد على الاستثمار في مشاريع إدارة المعرفة إلى أقصى حد. ومن الشعارات المناسبة في هذا المجال: «الإدارة الفعّالة للمعرفة هي 80% إدارة وتنظيم و20% تكنولوجيا».')

q(id='C9-07', ch=9, types=['كتاب'], qtype='MCQ', freq=1, src=['BKQ'], page=343,
  text='تسمى الشبكات الاجتماعية غير الرسمية للمهنيين والموظفين داخل الشركة وخارجها الذين لديهم أنشطة ومصالح مماثلة مرتبطة بالعمل بـ:',
  opts=['مجتمعات الممارسة Communities of Practice','مجتمعات الاكتشاف','المجتمعات ذات الاهتمام','مجتمعات المعرفة'],
  ans='مجتمعات الممارسة Communities of Practice (COPs)',
  exp='**مجتمعات الممارسة COPs** هي شبكات اجتماعية غير رسمية من المهنيين والموظفين داخل الشركة وخارجها الذين لديهم أنشطة واهتمامات مماثلة مرتبطة بالعمل. وتشمل أنشطتها التعليم الذاتي والتعليم الجماعي والمؤتمرات والرسائل الإخبارية عبر الإنترنت وتبادل الخبرات والتقنيات اليومية. وهي تسهّل إعادة استخدام المعرفة، وتقلل منحنى التعلم للموظفين الجدد، وتكون أرضية خصبة للأفكار والتقنيات الجديدة.')

q(id='C9-08', ch=9, types=['كتاب'], qtype='MCQ', freq=1, src=['BKQ'], page=344,
  text='ما هي الأنواع الرئيسية لأنظمة إدارة المعرفة؟',
  opts=['نظم المعلومات الإدارية، ونظم دعم القرارات، ونظم معالجة المعاملات','أنظمة المؤسسات وأنظمة دعم العملاء وأنظمة إدارة سلسلة التوريد','أنظمة إدارة قواعد البيانات وأنظمة الخبراء وأنظمة عمل المعرفة','أنظمة إدارة المعرفة على مستوى المؤسسة، وأنظمة عمل المعرفة، والتقنيات الذكية'],
  ans='أنظمة إدارة المعرفة على مستوى المؤسسة، وأنظمة عمل المعرفة KWS، والتقنيات الذكية',
  exp='هناك ثلاثة أنواع رئيسة لأنظمة إدارة المعرفة: **(1) أنظمة إدارة المعرفة على مستوى المؤسسة** — جهود عامة الغرض على مستوى الشركة لجمع المحتوى والمعرفة الرقمية وتخزينها وتوزيعها وتطبيقها. **(2) أنظمة عمل المعرفة KWS** — أنظمة متخصصة للمهندسين والعلماء والعاملين في مجال المعرفة (CAD، الواقع الافتراضي، الطباعة ثلاثية الأبعاد). **(3) التقنيات الذكية** — التنقيب في البيانات، الأنظمة الخبيرة، الشبكات العصبونية، المنطق الضبابي، الخوارزميات الجينية، الوكلاء الأذكياء.')

q(id='C9-09', ch=9, types=['دورة','كتاب'], qtype='MCQ', freq=2, src=['BKQ','R44'], page=355,
  text='ما هي الأداة التي تُستخدم لاكتشاف المعرفة Knowledge Discovery؟',
  opts=['أنظمة الخبراء','أنظمة معالجة المعاملات','التفكير القائم على الحالة','التنقيب في البيانات Data Mining'],
  ans='التنقيب في البيانات Data Mining',
  exp='يُستخدم **التنقيب في البيانات Data Mining** والشبكات العصبونية لاكتشاف المعرفة Knowledge Discovery، حيث يمكنهما اكتشاف الأنماط والفئات والسلوكيات الأساسية في مجموعات البيانات الكبيرة التي لا يمكن اكتشافها من قبل المديرين وحدهم أو ببساطة من خلال الخبرة. أما **الأنظمة الخبيرة والتبرير القائم على الحالة والمنطق الضبابي** فتُستخدم لالتقاط المعرفة الضمنية، و**الخوارزميات الجينية** لإيجاد حلول للمشكلات الكبيرة والمعقّدة.')

q(id='C9-10', ch=9, types=['دورة'], qtype='DEF', freq=3, src=['S25','F24','R44'], page=356,
  text='تعريف الأنظمة الخبيرة Expert Systems، وعلى أي قواعد تعمل؟',
  ans='تقنية ذكية لالتقاط المعرفة الضمنية في مجال محدد ومحدود من الخبرة البشرية، وتعمل من خلال مجموعة قواعد If-Then-Else مستخرَجة من الخبراء البشريين',
  exp='**الأنظمة الخبيرة Expert Systems** هي تقنية ذكية لالتقاط المعرفة الضمنية في مجال محدد ومحدود جداً من الخبرة البشرية. تستحوذ هذه الأنظمة على معرفة الموظفين المهرة في شكل **مجموعة من القواعد في نظام البرمجيات** يمكن استخدامها من قبل الآخرين في المؤسسة، وتعمل من خلال تطبيق **قواعد If-Then-Else** المستخرجة من الخبراء البشريين. وتؤدي عادة مهاماً محدودة جداً يمكن للمحترفين إنجازها في بضع دقائق أو ساعات قليلة، مثل تشخيص جهاز معطل أو تحديد ما إذا كان سيتم منح ائتمان لقرض.')

q(id='C9-11', ch=9, types=['دورة'], qtype='DEF', freq=3, src=['S25','F24','R44'], page=363,
  text='تعريف الوكيل الذكي Intelligent Agent',
  ans='تقنية ذكاء اصطناعي تساعد الشركات على التنقل عبر كميات كبيرة من البيانات لتحديد موقع المعلومات المهمة والتصرف وفقاً لها، وهي برامج تعمل دون تدخل بشري مباشر لتنفيذ مهام محددة',
  exp='**الوكيل الذكي Intelligent Agent** هو تقنية ذكاء اصطناعي تُستخدم في مساعدة الشركات على التنقل عبر كميات كبيرة من البيانات لتحديد موقع المعلومات التي تعتبر مهمة والتصرف وفقاً لها. والوكلاء الأذكياء برامج تعمل **دون تدخل بشري مباشر** لتنفيذ مهام محددة لمستخدم فردي أو إجراء عمل أو تطبيق برمجي. ويستخدم الوكيل قاعدة معرفية مدمجة لإنجاز المهام أو اتخاذ القرارات نيابة عن المستخدم، مثل حذف البريد الإلكتروني غير الهام أو جدولة المواعيد أو السفر عبر الشبكات للعثور على أرخص تذاكر الطيران. ومن أشكاله **روبوتات الدردشة Chatbots**.')

q(id='C9-12', ch=9, types=['دورة'], qtype='DEF', freq=1, src=['F24'], page=358,
  text='تعريف المنطق الضبابي Fuzzy Logic',
  ans='تقنية قائمة على القواعد يمكنها أن تمثّل عدم الدقة من خلال وضع قواعد تستخدم القيم التقريبية أو الذاتية',
  exp='**أنظمة المنطق الضبابي Fuzzy Logic Systems**: لا يفكّر معظم الناس بطريقة قواعد If-Then التقليدية أو بالأرقام الدقيقة؛ إذ يميل البشر إلى تصنيف الأشياء بشكل غير دقيق (رجل «قوي»، شركة «كبيرة»، حرارة «ساخنة»). فالمنطق الضبابي تقنية قائمة على القواعد يمكنها أن تمثّل عدم الدقة من خلال وضع قواعد تستخدم القيم التقريبية أو الذاتية، وتصف الظاهرة لغوياً ثم تمثّل الوصف بعدد صغير من القواعد المرنة. يوفّر حلولاً للمشكلات التي تتطلب خبرة يصعب تمثيلها في شكل قواعد واضحة، ويسمح بتغييرات تدريجية في المدخلات لإنتاج تغييرات سلسة في المخرجات بدلاً من المتقطعة. أمثلة تنظيمية: اختيار الموردين أو الكشف عن العيوب.')

q(id='C9-13', ch=9, types=['كتاب'], qtype='TF', freq=1, src=['BKQ'], page=337,
  text='تسمى المعرفة التي لا يتم توثيقها في أذهان الموظفين المعرفة الصريحة.',
  ans='خطأ',
  exp='العبارة خاطئة. التصحيح: المعرفة الموجودة في أذهان الموظفين والتي لم تُوثَّق تُسمى **المعرفة الضمنية Tacit Knowledge**، أما **المعرفة الصريحة Explicit Knowledge** فهي المعرفة التي تم توثيقها.')

q(id='C9-14', ch=9, types=['كتاب'], qtype='TF', freq=1, src=['BKQ'], page=337,
  text='يمكن أن تتواجد المعرفة في البريد الإلكتروني والبريد الصوتي والرسومات والمستندات غير المهيكلة بالإضافة إلى المستندات المهيكلة.',
  ans='صح',
  exp='العبارة صحيحة وهي نص الكتاب حرفياً: يمكن أن تتواجد المعرفة في البريد الإلكتروني والبريد الصوتي والرسومات والمستندات غير المهيكلة وكذلك المستندات المهيكلة. ويرتبط ذلك بأن نحو 80% من محتوى العمل في أي منظمة يكون شبه منظم أو غير منظم.')

q(id='C9-15', ch=9, types=['كتاب'], qtype='TF', freq=1, src=['BKQ'], page=340,
  text='تضيف كل خطوة في سلسلة قيمة إدارة المعرفة قيمة إلى البيانات والمعلومات الأولية عند تحويلها إلى معرفة قابلة للاستخدام.',
  ans='صح',
  exp='العبارة صحيحة. سلسلة قيمة إدارة المعرفة تتكون من أربع خطوات: اكتساب المعرفة، وتخزين المعرفة، ونشر المعرفة، وتطبيق المعرفة — وتضيف كل مرحلة في هذه السلسلة قيمة إلى البيانات والمعلومات الخام عند تحويلها إلى معرفة قابلة للاستخدام.')

q(id='C9-16', ch=9, types=['كتاب'], qtype='TF', freq=1, src=['BKQ'], page=346,
  text='المعرفة المهيكلة هي معرفة صريحة موجودة في الوثائق غير الرسمية.',
  ans='خطأ',
  exp='العبارة خاطئة. التصحيح: **المعرفة المنظّمة (المهيكلة) Structured Knowledge** هي المعرفة الواضحة والصريحة الموجودة في **الوثائق الرسمية** وكذلك في القواعد الرسمية التي تستمدها المنظمات من مراقبة الخبراء وسلوكياتهم في صنع القرار. أما ما يوجد في المجلدات والرسائل والمذكرات والاقتراحات والبريد الإلكتروني والعروض التقديمية فهو المعرفة **شبه المنظّمة أو غير المنظّمة**.')

q(id='C9-17', ch=9, types=['كتاب'], qtype='TF', freq=1, src=['BKQ'], page=350,
  text='عادة لا يملك العاملون في مجال المعرفة مستويات عالية من التعليم.',
  ans='خطأ',
  exp='العبارة خاطئة. التصحيح: **عادةً يتمتع العاملون في مجال المعرفة بمستويات عالية من التعليم** وينتمون إلى المنظمات المهنية، وغالباً ما يُطلب منهم ممارسة المحاكمة المنطقية والمستقلة للأمور باعتبارها جانباً روتينياً من عملهم. ويشمل عمال المعرفة الباحثين والمصممين والمعماريين والعلماء والمهندسين.')

q(id='C9-18', ch=9, types=['كتاب'], qtype='TF', freq=1, src=['BKQ'], page=350,
  text='تتسم نظم العمل المعرفي بخصائص تعكس الاحتياجات الخاصة للعاملين في مجال المعرفة.',
  ans='صح',
  exp='العبارة صحيحة. يحتاج العاملون في مجال المعرفة إلى نظم عمل معرفية عالية التخصص مع رسومات قوية وأدوات تحليلية وقدرات في مجال الاتصالات وإدارة مستندات. وتتطلب هذه الأنظمة قوة حوسبية كافية للتعامل مع الرسومات المتطورة أو الحسابات المعقّدة، ووصولاً سريعاً وسهلاً إلى قواعد البيانات الخارجية، وواجهات سهلة الاستخدام.')

q(id='C9-19', ch=9, types=['كتاب'], qtype='TF', freq=1, src=['BKQ'], page=355,
  text='تعتبر قواعد البيانات وجداول البيانات الأدوات الأساسية المستخدمة لاكتشاف المعرفة.',
  ans='خطأ',
  exp='العبارة خاطئة. التصحيح: الأدوات الأساسية المستخدمة **لاكتشاف المعرفة Knowledge Discovery** هي **التنقيب في البيانات Data Mining والشبكات العصبونية Neural Networks**، إذ يمكنهما اكتشاف الأنماط والفئات والسلوكيات الأساسية في مجموعات البيانات الكبيرة التي لا يمكن اكتشافها من قبل المديرين وحدهم. أما قواعد البيانات وجداول البيانات فهي أدوات تخزين ومعالجة لا اكتشاف.')

q(id='C9-20', ch=9, types=['كتاب'], qtype='TF', freq=1, src=['BKQ'], page=347,
  text='يمكن لبوابات المعرفة في المؤسسات توفير الوصول إلى مصادر المعلومات الخارجية مثل آخر الأخبار والبحوث.',
  ans='صح',
  exp='العبارة صحيحة. تمكّن أنظمة إدارة محتوى المؤسسة الرئيسية المستخدمين من الوصول إلى مصادر المعلومات الخارجية، مثل آخر الأخبار والأبحاث، والتواصل عبر البريد الإلكتروني والمحادثة والمراسلة الفورية ومجموعات المناقشة والمؤتمرات عبر الفيديو. وتمتلك هذه الأنظمة إمكانات وضع العلامات والتفاعل مع قواعد بيانات الشركة ومستودعات المحتوى **وإنشاء بوابات المعرفة الخاصة بالمؤسسة** التي توفر نقطة وصول واحدة إلى موارد المعلومات.')

q(id='C9-21', ch=9, types=['كتاب'], qtype='ESSAY', freq=1, src=['BKQ'], page=369,
  text='ما هي أنظمة إدارة المعرفة، وما هي أبعادها وما هو دورها في الأنظمة؟ {15 دقيقة – 15 من 100 – توجيه: الفقرة 9-1}',
  ans='إدارة المعرفة هي مجموعة إجراءات العمل لإنشاء المعرفة وتخزينها ونقلها وتطبيقها؛ وأبعاد المعرفة تشمل الضمنية/الصريحة والفردية/الجماعية؛ ودورها تعزيز التعلم التنظيمي والقيمة السوقية',
  exp='**التعريف**: إدارة المعرفة Knowledge Management تشير إلى مجموعة إجراءات العمل التي تم تطويرها في مؤسسة **لإنشاء المعرفة وتخزينها ونقلها وتطبيقها**، وهي تُزيد من قدرة المنظمة على التعلم من بيئتها ودمج المعرفة في عملياتها التجارية. **أبعاد المعرفة**: (أ) الفرق بين **البيانات والمعلومات والمعرفة والحكمة**. (ب) المعرفة **ضمنية Tacit** (في أذهان الموظفين وغير موثّقة) أو **صريحة Explicit** (موثّقة). (ج) المعرفة سمة **فردية وجماعية** للشركة، وهي حدث معرفي بل وفيزيولوجي يحدث داخل رؤوس الأشخاص. (د) المعرفة **ظرفية وسياقية** ومرتبطة بالشخص وليست قابلة للتطبيق على المستوى العام. (هـ) المعرفة أصل مختلف عن الأصول الثابتة، ويصعب تقليدها. **الدور**: الكفاءات الأساسية القائمة على المعرفة هي أصول تنظيمية رئيسة ومصدر للربح والميزة التنافسية؛ وجزء كبير من قيمة سوق الأوراق المالية للشركة مرتبط بأصولها غير الملموسة التي تشكّل المعرفة أحد مكوناتها. **سلسلة قيمة إدارة المعرفة**: اكتساب – تخزين – نشر – تطبيق، مع رأس المال التنظيمي والإداري (80% إدارة وتنظيم، 20% تكنولوجيا).')

q(id='C9-22', ch=9, types=['كتاب'], qtype='ESSAY', freq=1, src=['BKQ'], page=369,
  text='ما هي أنواع الأنظمة المستخدمة لإدارة المعرفة على مستوى المنظمة؟ اشرح مكوناتها وادعم الإجابة بالأمثلة. {15 دقيقة – 15 من 100 – توجيه: الفقرة 9-2}',
  ans='أنظمة إدارة محتوى المؤسسة ECM، وأنظمة تحديد الخبرات ومشاركتها، وأنظمة إدارة التعلم LMS',
  exp='**(1) أنظمة إدارة محتوى المؤسسة Enterprise Content Management (ECM)**: تساعد على إدارة نوعَي المعرفة — **المنظّمة Structured** (المعرفة الصريحة في الوثائق الرسمية والقواعد الرسمية) و**شبه المنظّمة** (نحو 80% من محتوى العمل: المجلدات، الرسائل، المذكرات، الاقتراحات، البريد الإلكتروني، الرسومات، العروض التقديمية، الفيديو). لها قدرات على التقاط المعرفة وتخزينها واسترجاعها وتوزيعها وحفظها. المشكلة الرئيسة فيها هي إنشاء **نظام تصنيف Taxonomy** مناسب لتنظيم المعلومات في فئات ذات مغزى. موردون: Open Text و EMC و IBM و Oracle. وتوجد **أنظمة إدارة الأصول الرقمية Digital Asset Management** للبيانات غير المنظّمة (صور، فيديو، صوت) — مثال Coca-Cola لتتبع صور علامتها التجارية. **(2) تحديد الخبرات ومشاركتها**: بعض المعرفة تقيم في ذاكرة الخبراء الأفراد وليست وثيقة رقمية؛ فتوفّر الأنظمة أدلة إلكترونية لخبراء الشركة وملفاتهم الشخصية وتفاصيل خبرتهم ومشاريعهم ومنشوراتهم، وأدوات وضع العلامات المرجعية Social Bookmarking لمشاركة الروابط والوسوم. **(3) أنظمة إدارة التعلم Learning Management Systems (LMS)**: توفّر أدوات لإدارة وتسليم وتتبع وتقييم أنواع التعلم والتدريب، وتدعم أساليب متعددة (بث الفيديو، الندوات عبر الإنترنت، الصفوف الافتراضية، المنتديات والدردشة)، وتلجأ الشركات أيضاً إلى **الدورات الضخمة المفتوحة MOOCs**.')

q(id='C9-23', ch=9, types=['كتاب'], qtype='ESSAY', freq=1, src=['BKQ'], page=369,
  text='تكلم عن أنظمة عمل المعرفة التالية: التصميم بمساعدة الكمبيوتر – الطباعة ثلاثية الأبعاد – أنظمة الواقع الافتراضي – الواقع المعزّز. {15 دقيقة – 15 من 100 – توجيه: الفقرة 9-3}',
  ans='CAD للنمذجة والتصميم الآلي، والطباعة ثلاثية الأبعاد للتصنيع الجاهز طبقة فوق طبقة، والواقع الافتراضي للمحاكاة الغامرة، والواقع المعزّز لدمج الصور الافتراضية بالعالم الحقيقي',
  exp='**(1) التصميم بمساعدة الكمبيوتر CAD**: إنشاء التصميمات ومراجعتها تلقائياً باستخدام أجهزة الكمبيوتر وبرامج الرسوميات المعقّدة. في المنهجية التقليدية يتطلب كل تعديل صنع قالب ونموذج أولي واختباره مادياً، وهي عملية مكلفة وطويلة؛ أما مع محطة عمل CAD فيحتاج المصمم إلى نموذج أولي فعلي واحد فقط في نهاية العملية. وقدرة CAD على توفير مواصفات التصميم لعمليات التصنيع توفّر الوقت والمال. أشهرها AutoCAD و 3ds Max Design. **(2) الطباعة ثلاثية الأبعاد 3-D Printing** (التصنيع الجاهز Additive Manufacturing): تستخدم آلات لصنع الأشياء الصلبة **طبقة تلو الأخرى** من مواصفات موجودة في ملف رقمي، على عكس التقنيات التقليدية التي تقطع أو تحفر الأشياء من القوالب — مما يقلّل إهدار المواد. تُستخدم للنماذج الأولية والتصنيع المخصص وعمليات الإنتاج الصغيرة، وتتعامل مع البلاستيك والمعدن والغشاء البلاستيكي والتيتانيوم والغضاريف البشرية، وتنتج مكونات فعّالة كالبطاريات والترانزستورات ومصابيح LED. **(3) أنظمة الواقع الافتراضي VR**: تمتلك إمكانات إظهار وعرض ومحاكاة تتجاوز قدرات CAD التقليدية، وتستخدم برمجيات رسوميات تفاعلية لإنشاء محاكاة قريبة جداً من الواقع بحيث يعتقد المستخدمون أنهم يشاركون في موقف حقيقي. يرتدي المستخدم ملابس خاصة وأغطية رأس ومعدات تحتوي أجهزة استشعار تسجّل حركاته وتنقلها للكمبيوتر، مع نظارات فيديو ومرفقات صوتية وقفازات. **(4) الواقع المعزّز AR**: تقنية لتحسين الإظهار توفّر رؤية وعرضاً مباشراً أو غير مباشر لبيئة فعلية في العالم الحقيقي يتم تعزيز عناصرها بصور افتراضية ينشئها الكمبيوتر. يُوضع المستخدم في العالم المادي الحقيقي ثم تُدمج الصور الافتراضية مع العرض الحقيقي. أمثلة: علامات الإنذار الصفراء في مباريات كرة القدم المتلفزة، والجراحة الموجهة بالصور، والتدريب العسكري والتصميم الهندسي والروبوتات. وتستخدم تطبيقات الويب معيار **VRML**.')

# ============================ CHAPTER 10 ============================

q(id='C10-01', ch=10, types=['دورة','كتاب'], qtype='MCQ', freq=2, src=['BKQ','R44'], page=381,
  text='ما هو التسلسل الصحيح لخطوات عملية اتخاذ القرار؟',
  opts=['جمع المعلومات – التصميم – الاختيار – التنفيذ','جمع المعلومات – الاختيار – التصميم – التنفيذ','التصميم – جمع المعلومات – الاختيار – التنفيذ','الاختيار – جمع المعلومات – التصميم – التنفيذ'],
  ans='جمع المعلومات – التصميم – الاختيار – التنفيذ',
  exp='وصف **سيمون Simon (1960)** أربع مراحل مختلفة في صنع القرار: **(1) جمع المعلومات Intelligence** — اكتشاف المشاكل التي تحدث في المنظمة وتحديدها وفهمها بتحديد سبب المشكلة ومكانها وآثارها. **(2) التصميم Design** — تحديد واستكشاف الحلول المختلفة للمشكلة. **(3) الاختيار Choice** — الانتقاء من بين بدائل الحل. **(4) التنفيذ Implementation** — القيام بالعمل بالبديل المختار والاستمرار في مراقبة مدى نجاح الحل. ويمكن العودة إلى مرحلة سابقة وتكرار العملية إذا لم يؤتِ الحل ثماره.')

q(id='C10-02', ch=10, types=['دورة','كتاب'], qtype='MCQ', freq=3, src=['BKQ','S25','F24'], page=384,
  text='وفي إطار _____________ الذي يضطلع به المديرون، يعملون كمراكز عصبية لمنظماتهم، حيث يتلقون المعلومات المحدّثة والأكثر واقعية ويعيدون توزيعها على أولئك الذين يحتاجون أن يكونوا على دراية بها:',
  opts=['الدور الشخصي','الدور الإعلامي Informational Roles','دور اتخاذ القرارات','دور القائد'],
  ans='الدور الإعلامي Informational Roles',
  exp='في إطار **الدور الإعلامي Informational Roles** الذي يضطلع به المديرون، يعملون كمراكز عصبية لمنظماتهم، حيث يتلقون المعلومات المحدّثة والأكثر واقعية ويعيدون توزيعها على أولئك الذين يحتاجون أن يكونوا على دراية بها؛ فالمديرون هم ناشرون للمعلومات ومتحدثون باسم منظماتهم. والأدوار الإدارية العشرة عند **Mintzberg** تندرج في ثلاث فئات: **الشخصية** (رمز، قائد، جهة اتصال)، و**الإعلامية** (مركز عصبي، ناشر، متحدث)، و**القرارية** (رجل أعمال، معالج اضطرابات، مخصص موارد، مفاوض).')

q(id='C10-03', ch=10, types=['دورة','كتاب'], qtype='MCQ', freq=3, src=['BKQ','S25','F24'], page=401,
  text='تُسمى عملية توصيل ذكاء الأعمال للعاملين في مجال المعرفة الذين يحتاجون إليها بـ:',
  opts=['تحصيل البيانات','فلترة المعلومات','تحليل ذكاء الأعمال','نشر النتائج Publish Results'],
  ans='نشر النتائج Publish Results',
  exp='**الأنشطة الرئيسة الثلاثة في عملية ذكاء الأعمال**: (1) **تحصيل البيانات Data Acquisition**، (2) **تحليل ذكاء الأعمال BI Analysis**، (3) **نشر النتائج Publish Results** وهي عملية توصيل ذكاء الأعمال للعاملين في مجال المعرفة الذين يحتاجون إليها. ويكون النشر إما **بالدفع Push Publishing** (تسليم نتائج وفقاً لجدول زمني أو نتيجة لحدث أو حالة بيانات معينة دون طلب) أو **بالسحب Pull Publishing** (يطلب المستخدم النتائج صراحةً).')

q(id='C10-04', ch=10, types=['دورة','كتاب'], qtype='MCQ', freq=2, src=['BKQ','F24'], page=401,
  text='تُسمى عملية الحصول على بيانات المصدر وتنظيفها وتنظيمها وربطها وفهرستها بـ:',
  opts=['تحصيل البيانات Data Acquisition','فلترة المعلومات','تحليل ذكاء الأعمال','نشر النتائج'],
  ans='تحصيل البيانات Data Acquisition',
  exp='**تحصيل البيانات Data Acquisition** هي عملية الحصول على بيانات المصدر وتنظيفها وتنظيمها وربطها وفهرستها. وهي أول الأنشطة الرئيسة الثلاثة في عملية ذكاء الأعمال، تليها **تحليل ذكاء الأعمال** (وفئاته الثلاث: إعداد التقارير، والتنقيب في البيانات، والبيانات الضخمة)، ثم **نشر النتائج**.')

q(id='C10-05', ch=10, types=['دورة','كتاب'], qtype='MCQ', freq=3, src=['BKQ','S25','F24'], page=392,
  text='ما هو النظام الذي وظائفه: الحصول على البيانات – تنظيف البيانات – تنظيم البيانات وربطها – كتالوج البيانات؟',
  opts=['مستودع البيانات Data Warehouse','منفذ البيانات Data Mart','قاعدة البيانات التشغيلية','نظام Hadoop'],
  ans='مستودع البيانات Data Warehouse',
  exp='**مستودع البيانات Data Warehouse** هو نظام لإدارة بيانات ذكاء الأعمال الخاصة بالمنظمة، ووظائفه الأربع كما يعدّدها الكتاب: **الحصول على البيانات – تنظيف البيانات – تنظيم البيانات وربطها – كتالوج البيانات**. و«تهجير البيانات» ليس من وظائفه.')

q(id='C10-06', ch=10, types=['كتاب'], qtype='MCQ', freq=2, src=['BKQ','R44'], page=392,
  text='ما هو الخيار الذي لا يُعتبر من وظائف مستودع البيانات؟',
  opts=['الحصول على البيانات','تنظيف البيانات','تنظيم البيانات وربطها','تهجير البيانات'],
  ans='تهجير البيانات',
  exp='وظائف مستودع البيانات كما وردت في الكتاب أربع فقط: الحصول على البيانات – تنظيف البيانات – تنظيم البيانات وربطها – كتالوج البيانات. أما **تهجير البيانات Data Migration** فليس من وظائفه المذكورة.')

q(id='C10-07', ch=10, types=['كتاب'], qtype='MCQ', freq=1, src=['BKQ'], page=391,
  text='ما هي المهمة التي لا تُعتبر من المهام التعاونية لأنظمة ذكاء الأعمال BI؟',
  opts=['تقييم الأداء','الإعلام والاستعلام','اتخاذ القرارات','حل المشكلات'],
  ans='تقييم الأداء',
  exp='تستخدم المنظمات ذكاء الأعمال لأربع مهام تعاونية فقط: **(1) الإعلام والاستعلام** (التعرّف على كيفية استخدام العملاء للنظام أو تصفّح النتائج). **(2) اتخاذ القرارات** (تحديد خصائص الأحداث التي تولّد أكبر إيرادات). **(3) حل المشكلات** (الفرق بين الوضع الحالي والوضع المرغوب). **(4) إدارة المشروع**. وهذه المهام هرمية: اتخاذ القرار يتطلب الاستعلام، وحل المشكلات يتطلب اتخاذ القرار والإعلام، وإدارة المشروع تتطلب الثلاثة. أما «تقييم الأداء» فليس منها.')

q(id='C10-08', ch=10, types=['دورة'], qtype='MCQ', freq=2, src=['HD','F24'], page=396,
  text='تقدّم نظم MIS و DSS و ESS المعلومات والمعرفة لمختلف الأشخاص والمستويات في الشركة — هذه تمثّل أي عنصر من عناصر بيئة ذكاء الأعمال؟',
  opts=['منصة التسليم Delivery Platform','بيانات بيئة الأعمال','البنية التحتية لذكاء الأعمال','مجموعة أدوات تحليلات الأعمال'],
  ans='منصة التسليم Delivery Platform',
  exp='عناصر بيئة ذكاء الأعمال الستة: (1) بيانات من بيئة الأعمال، (2) البنية التحتية لذكاء الأعمال، (3) مجموعة أدوات تحليلات الأعمال، (4) الأساليب الإدارية والمستخدمون، (5) **منصة التسليم — MIS و DSS و ESS**، (6) واجهة المستخدم. وتقدّم نظم MIS و DSS و ESS المعلومات والمعرفة لمختلف الأشخاص والمستويات في الشركة: الموظفون التشغيليون والمديرون المتوسطون وكبار المسؤولين التنفيذيين.')

q(id='C10-09', ch=10, types=['دورة'], qtype='DEF', freq=3, src=['HD','F24','R44'], page=389,
  text='تعريف ذكاء الأعمال Business Intelligence (BI) وما هي مكوناته؟',
  ans='البنية التحتية للتخزين والتكامل والإبلاغ وتحليل البيانات التي تأتي من بيئة الأعمال بما في ذلك البيانات الضخمة؛ ومكوناته الخمسة: الأجهزة والبرامج والبيانات والإجراءات والأشخاص',
  exp='**ذكاء الأعمال Business Intelligence** مصطلح يستخدمه موردو الأجهزة والبرامج ومستشارو تكنولوجيا المعلومات لوصف **البنية التحتية للتخزين والتكامل والإبلاغ وتحليل البيانات** التي تأتي من بيئة الأعمال، بما في ذلك البيانات الضخمة. وهو يشمل **قواعد البيانات ومستودعات البيانات ومخازن البيانات وأنظمة Hadoop والمنصات التحليلية**. وكنظام معلومات تحتوي أنظمة BI على خمسة مكونات قياسية: **الأجهزة والبرامج والبيانات والإجراءات والأشخاص**. ويُميَّز عنه **تحليلات الأعمال Business Analytics** الذي يركّز أكثر على الأدوات والتقنيات لتحليل البيانات وفهمها مثل OLAP والإحصاءات والنماذج والتنقيب في البيانات.')

q(id='C10-10', ch=10, types=['دورة','كتاب'], qtype='DEF', freq=3, src=['S25','HD','F24'], page=378,
  text='تعريف القرارات غير المهيكلة Unstructured Decisions',
  ans='القرارات التي يجب أن يقدّم فيها صانع القرار الحكم والتقييم والبصيرة لحل المشكلة، وهي جديدة ومهمة وغير روتينية ولا يوجد إجراء مفهوم أو متفق عليه لاتخاذها',
  exp='**القرارات غير المهيكلة Unstructured Decisions** هي تلك التي يجب أن يقدّم فيها صانع القرار الحكم والتقييم والبصيرة لحل المشكلة. وكل من هذه القرارات جديد ومهم وغير روتيني، ولا يوجد إجراء مفهوم بشكل جيد أو متفق عليه لاتخاذها. وهي أكثر شيوعاً في **المستويات العليا** للشركة. مثال: تحديد أهداف الشركة التي تمتد لخمس أو عشر سنوات، أو دخول أسواق جديدة.')

q(id='C10-11', ch=10, types=['دورة'], qtype='DEF', freq=2, src=['F24','R44'], page=379,
  text='تعريف القرارات المهيكلة Structured Decisions',
  ans='قرارات متكررة وروتينية ومنظّمة وغير جديدة، وتنطوي على إجراء محدد لمعالجتها، وتنتشر في المستويات التنظيمية الأدنى',
  exp='**القرارات المهيكلة Structured Decisions** متكررة وروتينية، وتنطوي على إجراء محدد لمعالجتها بحيث لا يتعين التعامل معها في كل مرة كما لو كانت جديدة، وهي أكثر انتشاراً في **المستويات التنظيمية الأدنى**. مثال الكتاب: المشرف على خط التجميع يقرر ما إذا كان العامل المأجور بالساعة يستحق أجر العمل الإضافي إذا عمل أكثر من ثماني ساعات؛ وممثل حساب المبيعات يمنح الائتمان بالرجوع إلى قاعدة بيانات معايير الشركة.')

q(id='C10-12', ch=10, types=['دورة'], qtype='DEF', freq=1, src=['HD'], page=379,
  text='تعريف القرارات شبه المهيكلة Semi-structured Decisions',
  ans='قرارات تحتوي على عناصر من كلا النوعين، حيث يكون لجزء فقط من المشكلة إجابة واضحة يتم توفيرها من خلال إجراء مقبول',
  exp='**القرارات شبه المهيكلة Semi-structured Decisions**: تحتوي على عناصر من كلا النوعين السابقين (المهيكلة وغير المهيكلة)، حيث يكون **لجزء فقط من المشكلة** إجابة واضحة يتم توفيرها من خلال إجراء مقبول. وهي أكثر شيوعاً في المستويات التنظيمية المتوسطة. مثال: تقرير تنفيذ يُظهر انخفاضاً في الطلب في مركز توزيع معين يحتاج جزءاً منظّماً (تقرير من نظام المؤسسة) وجزءاً غير منظّم (مقابلات الموظفين والظروف الاقتصادية المحلية).')

q(id='C10-13', ch=10, types=['كتاب'], qtype='TF', freq=1, src=['BKQ'], page=383,
  text='يلعب المديرون أدواراً رئيسة في المنظمات، حيث تتراوح مسؤولياتهم بين اتخاذ القرارات وكتابة التقارير وحضور الاجتماعات وترتيب اللقاءات.',
  ans='صح',
  exp='العبارة صحيحة وهي نص الكتاب حرفياً في مطلع الفقرة 10-2-1. ويمكن فهم الوظائف والأدوار الإدارية بشكل أفضل من خلال دراسة النماذج الكلاسيكية والمعاصرة للسلوك الإداري.')

q(id='C10-14', ch=10, types=['كتاب'], qtype='TF', freq=1, src=['BKQ'], page=386,
  text='حتى مع توفر المعلومات الدقيقة في الوقت المناسب، غالباً ما يتخذ المديرون قرارات سيئة.',
  ans='صح',
  exp='العبارة صحيحة. يذكر الكتاب ثلاثة أسباب لعدم إسفار الاستثمارات في تكنولوجيا المعلومات عن نتائج إيجابية دائماً: **جودة المعلومات**، و**عوامل تصفية الإدارة**، و**الثقافة التنظيمية**. فالمديرون — مثل جميع البشر — يستوعبون المعلومات من خلال سلسلة من الفلاتر، ولا يقيّمون المخاطر بشكل صحيح، ويتخذون القرارات بناءً على الحدس والمشاعر وتأطير المشكلة بدلاً من البيانات التجريبية.')

q(id='C10-15', ch=10, types=['كتاب'], qtype='TF', freq=1, src=['BKQ'], page=408,
  text='تقوم الإدارة العليا عموماً بمراقبة أداء الجوانب الرئيسة للعمل، بدءاً من تعطل الآلات في المصانع إلى المبيعات اليومية أو حركة المرور اليومية على موقع الشركة على الويب.',
  ans='خطأ',
  exp='العبارة خاطئة. التصحيح: هذا وصف لدور **الإدارة التشغيلية والوسطى** وليس الإدارة العليا. يقول الكتاب: «تقوم الإدارة التشغيلية والوسطى عموماً بمراقبة أداء الجوانب الرئيسة للعمل، بدءاً من تعطل الآلات في المصنع إلى المبيعات اليومية أو حركة المرور اليومية على موقع الشركة على الويب». أما الإدارة العليا فتركّز على القضايا الاستراتيجية والاتجاهات طويلة الأجل وتستخدم ESS ولوحات القيادة وبطاقة الأداء المتوازن.')

q(id='C10-16', ch=10, types=['كتاب'], qtype='TF', freq=1, src=['BKQ'], page=389,
  text='تحتوي أنظمة BI على خمسة مكونات قياسية: الأجهزة والبرامج والبيانات والإجراءات والأشخاص.',
  ans='صح',
  exp='العبارة صحيحة. كنظام معلومات، تحتوي أنظمة ذكاء الأعمال BI على خمسة مكونات قياسية: **الأجهزة والبرامج والبيانات والإجراءات والأشخاص**. ويسمى المكوّن البرمجي لنظام ذكاء الأعمال بـ«تطبيق BI».')

q(id='C10-17', ch=10, types=['كتاب'], qtype='TF', freq=1, src=['BKQ'], page=391,
  text='تتمحور مهمة «الإعلام والاستعلام» في أنظمة BI حول تحديد خصائص الأحداث التي تولّد أكبر إيرادات.',
  ans='خطأ',
  exp='العبارة خاطئة. التصحيح: تحديد خصائص الأحداث التي تولّد أكبر إيرادات هي مهمة **اتخاذ القرارات Decision Making**. أما **الإعلام والاستعلام** فتتمحور حول التعرّف على كيفية استخدام العملاء للنظام الجديد أو تصفّح النتائج لبعض الأغراض المستقبلية غير المحددة.')

q(id='C10-18', ch=10, types=['كتاب'], qtype='TF', freq=1, src=['BKQ'], page=392,
  text='تكون البيانات التشغيلية غير منظّمة وغير مهيكلة، وتُستخدم لمعالجة المعاملات بسرعة وبشكل موثوق.',
  ans='خطأ',
  exp='العبارة خاطئة. التصحيح: البيانات التشغيلية تكون **منظّمة ومهيكلة** لمعالجة المعاملات بسرعة وبشكل موثوق — وهذا بالضبط سبب كونها غير مناسبة للتحليل، لأنها نادراً ما تُنظَّم بطريقة تدعم التحليل بسهولة. ولهذا السبب (إضافة إلى الأمن والتحكم وأثر التحليلات الثقيلة على أداء نظم التشغيل) تستخرج المؤسسات بياناتها التشغيلية إلى مستودع بيانات للمعالجة التحليلية.')

q(id='C10-19', ch=10, types=['كتاب'], qtype='TF', freq=1, src=['BKQ'], page=393,
  text='مستودع البيانات هو عبارة عن تجميع للبيانات، يكون عادةً أصغر من مجمّع البيانات، ويعالج احتياجات قسم معين أو مجال وظيفي محدد ضمن المؤسسة.',
  ans='خطأ',
  exp='العبارة خاطئة والوصف مقلوب. **التصحيح**: هذا هو تعريف **منفذ / مجمّع البيانات Data Mart** — فهو الأصغر ويعالج احتياجات قسم معين أو مجال وظيفي محدد. أما **مستودع البيانات Data Warehouse** فهو الأكبر ويخدم المؤسسة بأكملها ويخزّن المعطيات الحالية والتاريخية التي تهم صانعي القرار في جميع أنحاء الشركة.')

q(id='C10-20', ch=10, types=['كتاب'], qtype='TF', freq=1, src=['BKQ'], page=205,
  text='البيانات الكبيرة Big Data هو مصطلح يُستخدم لوصف مجموعات البيانات التي تتميز بحجم ضخم وسرعة عالية وتنوع كبير.',
  ans='صح',
  exp='العبارة صحيحة. يُستخدم مصطلح **البيانات الضخمة Big Data** لوصف مجموعات البيانات ذات الأحجام الكبيرة والمتغيرة بسرعة لدرجة أنها تتجاوز قدرة نظم إدارة قواعد البيانات التقليدية على التقاطها وتخزينها وتحليلها. ولا تشير إلى كمية محددة لكنها تشير عادة إلى البيانات في نطاق بيتابايت أو إكسابايت. وهذه هي خصائص الحجم Volume والسرعة Velocity والتنوع Variety.')

q(id='C10-21', ch=10, types=['كتاب'], qtype='ESSAY', freq=1, src=['BKQ'], page=418,
  text='ما هي الأنواع الثلاثة للقرارات؟ اشرح مراحل عملية صنع القرار. {15 دقيقة – 15 من 100 – توجيه: الفقرة 10-1}',
  ans='المهيكلة وغير المهيكلة وشبه المهيكلة؛ ومراحل سيمون الأربع: جمع المعلومات، التصميم، الاختيار، التنفيذ',
  exp='**أنواع القرارات**: (1) **غير المهيكلة Unstructured** — يقدّم فيها صانع القرار الحكم والتقييم والبصيرة؛ جديدة ومهمة وغير روتينية ولا يوجد إجراء متفق عليه لاتخاذها؛ أكثر شيوعاً في المستويات العليا. (2) **المهيكلة Structured** — متكررة وروتينية وتنطوي على إجراء محدد لمعالجتها؛ أكثر انتشاراً في المستويات الأدنى. (3) **شبه المهيكلة Semi-structured** — تحتوي عناصر من النوعين، حيث يكون لجزء فقط من المشكلة إجابة واضحة من خلال إجراء مقبول؛ أكثر شيوعاً في المستويات المتوسطة. **مراحل صنع القرار (سيمون 1960)**: (أ) **جمع المعلومات Intelligence** — اكتشاف المشاكل وتحديدها وفهمها بتحديد سببها ومكانها وآثارها على المنظمة. (ب) **التصميم Design** — تحديد واستكشاف الحلول المختلفة للمشكلة. (ج) **الاختيار Choice** — الانتقاء من بين بدائل الحل. (د) **التنفيذ Implementation** — القيام بالعمل بالبديل المختار والاستمرار في مراقبة مدى نجاح الحل. ويمكن **العودة إلى مرحلة سابقة وتكرار العملية** إذا لم يؤتِ الحل ثماره.')

q(id='C10-22', ch=10, types=['كتاب'], qtype='ESSAY', freq=1, src=['BKQ'], page=418,
  text='عرّف ذكاء الأعمال وتحدث عن الأنشطة الرئيسة التي يتضمنها. {15 دقيقة – 15 من 100 – توجيه: الفقرة 10-3}',
  ans='التعريف والمكونات الخمسة، ثم الأنشطة الثلاثة: تحصيل البيانات، تحليل ذكاء الأعمال، نشر النتائج',
  exp='**التعريف**: ذكاء الأعمال BI هو البنية التحتية للتخزين والتكامل والإبلاغ وتحليل البيانات التي تأتي من بيئة الأعمال بما في ذلك البيانات الضخمة. تقوم البنية التحتية بجمع المعلومات ذات الصلة وتخزينها وتنظيفها وإتاحتها للمديرين. ويشمل قواعد البيانات ومستودعات البيانات ومخازن البيانات وأنظمة Hadoop والمنصات التحليلية. مكوناته الخمسة: الأجهزة والبرامج والبيانات والإجراءات والأشخاص. **الأنشطة الرئيسة الثلاثة**: (1) **تحصيل البيانات Data Acquisition** — الحصول على بيانات المصدر وتنظيفها وتنظيمها وربطها وفهرستها. (2) **تحليل ذكاء الأعمال BI Analysis** — عملية إنشاء ذكاء الأعمال، وفئاته الأساسية الثلاث: التقارير، والتنقيب في البيانات Data Mining، والبيانات الضخمة Big Data. (3) **نشر النتائج Publish Results** — توصيل ذكاء الأعمال للعاملين في مجال المعرفة الذين يحتاجون إليه، إما **بالدفع Push** (وفق جدول زمني أو حدث) أو **بالسحب Pull** (بطلب صريح من المستخدم)، عبر التقارير المطبوعة أو مخدمات الويب أو مخدمات التقارير.')

q(id='C10-23', ch=10, types=['كتاب'], qtype='ESSAY', freq=1, src=['BKQ'], page=418,
  text='كيف يُستخدم ذكاء الأعمال وتحليلات الأعمال في دعم اتخاذ القرار؟ {15 دقيقة – 15 من 100 – توجيه: الفقرة 10-4}',
  ans='دعم مختلف المستويات: التشغيلية والوسطى بالتقارير وتحليل الحساسية والجداول المحورية، والعليا ببطاقة الأداء المتوازن وإدارة أداء الأعمال ولوحات القيادة، والجماعية بنظم GDSS',
  exp='**(أ) دعم الإدارة التشغيلية والوسطى**: تراقب أداء الجوانب الرئيسة للعمل. تُستخدم **نظم MIS** لدعم القرارات المهيكلة عبر تقارير إلكترونية و**تقارير الاستثناءات Exception Reports** التي تسلّط الضوء على الظروف الاستثنائية فقط. **دعم القرارات شبه المهيكلة**: تُستخدم **نظم DSS** التي تعتمد على النمذجة أكثر من MIS، وتستخدم **تحليل «ماذا لو» What-If** لتغيير قيم معينة والتنبؤ بالنتائج، و**تحليل الحساسية Sensitivity Analysis** الذي يطرح أسئلة «ماذا لو» بشكل متكرر للتنبؤ بمجموعة من النتائج عند تغيير متغير أو أكثر. كما تُستخدم **المعالجة التحليلية متعددة الأبعاد OLAP** و**الجدول المحوري Pivot Table** في Excel لتحديد وفهم الأنماط. **(ب) دعم الإدارة العليا**: الغرض من **نظم ESS** مساعدة المديرين التنفيذيين على التركيز على معلومات الأداء المهمة. **طريقة بطاقة الأداء المتوازن Balanced Scorecard** — إطار عمل لتفعيل الخطة الإستراتيجية بالتركيز على نتائج قابلة للقياس في أربعة أبعاد: **المالية، والعمليات التجارية، والعملاء، والتعلم والنمو** — ويُقاس الأداء في كل بُعد باستخدام **مؤشرات الأداء الرئيسة KPIs**. وتُسمى «متوازنة» لأنها تجعل المديرين يركزون على أكثر من الأداء المالي وحده. و**إدارة أداء الأعمال BPM** تترجم استراتيجيات الشركة إلى أهداف تشغيلية ومؤشرات أداء رئيسة. **(ج) نظم دعم القرار الجماعي GDSS**: بيئات تعاون تساعد مجموعة من صانعي القرار على العمل معاً لحل المشكلات غير المهيكلة، سواء في الموقع نفسه أو في مواقع مختلفة، وقد حلّت غرف التعاون الافتراضية (Cisco CMR، Skype for Business) محل الغرف المخصصة المكلفة.')
